// Authoritative REWARD pool (T4 parity). Not generated by gen_sts2_tables: the reward
// pool is profile-dependent (epoch unlocks), so it is kept as an explicit table matching
// the parity harness profile's CardPool.GetUnlockedCards order. Reward rolls draw by
// INDEX into this list, so the order is part of the contract.
#include "sts2/Sts2Battle.h"
#include "sts2/Sts2Ids.h"

#include <cstring>

namespace sts2 {

namespace {

const CardId kRewardPool_IRONCLAD[] = {
    CardId::AGGRESSION, CardId::ANGER, CardId::ARMAMENTS, CardId::ASHEN_STRIKE, CardId::BARRICADE, CardId::BASH, CardId::BATTLE_TRANCE, CardId::BLOODLETTING,
    CardId::BLUDGEON, CardId::BODY_SLAM, CardId::BRAND, CardId::BREAK, CardId::BREAKTHROUGH, CardId::BULLY, CardId::BURNING_PACT, CardId::CASCADE,
    CardId::COLOSSUS, CardId::CONFLAGRATION, CardId::CORRUPTION, CardId::CRIMSON_MANTLE, CardId::DARK_EMBRACE, CardId::DEFEND_IRONCLAD, CardId::DEMON_FORM, CardId::DISMANTLE,
    CardId::EVIL_EYE, CardId::EXPECT_A_FIGHT, CardId::FEED, CardId::FEEL_NO_PAIN, CardId::FIEND_FIRE, CardId::FIGHT_ME, CardId::FLAME_BARRIER, CardId::FORGOTTEN_RITUAL,
    CardId::HAVOC, CardId::HEADBUTT, CardId::HELLRAISER, CardId::HEMOKINESIS, CardId::HOWL_FROM_BEYOND, CardId::IMPERVIOUS, CardId::INFERNAL_BLADE, CardId::INFLAME,
    CardId::IRON_WAVE, CardId::JUGGERNAUT, CardId::JUGGLING, CardId::MANGLE, CardId::NOT_YET, CardId::OFFERING, CardId::ONE_TWO_PUNCH, CardId::PERFECTED_STRIKE,
    CardId::PILLAGE, CardId::POMMEL_STRIKE, CardId::PRIMAL_FORCE, CardId::PYRE, CardId::RAGE, CardId::RAMPAGE, CardId::RUPTURE, CardId::SECOND_WIND,
    CardId::SETUP_STRIKE, CardId::SHRUG_IT_OFF, CardId::SPITE, CardId::STAMPEDE, CardId::STOKE, CardId::STOMP, CardId::STONE_ARMOR, CardId::STRIKE_IRONCLAD,
    CardId::SWORD_BOOMERANG, CardId::TAUNT, CardId::THRASH, CardId::THUNDERCLAP, CardId::TREMBLE, CardId::TRUE_GRIT, CardId::TWIN_STRIKE, CardId::UNMOVABLE,
    CardId::UNRELENTING, CardId::UPPERCUT, CardId::VICIOUS, CardId::WHIRLWIND,
};

struct RewardPoolEntry { const char* pool; const CardId* cards; int count; };
const RewardPoolEntry kRewardPools[] = {
    {"IRONCLAD", kRewardPool_IRONCLAD, 76},
};

} // namespace

const CardId* sts2RewardPool(const char* pool, int* count) {
    for (const auto& e : kRewardPools) {
        if (std::strcmp(e.pool, pool) == 0) {
            if (count) *count = e.count;
            return e.cards;
        }
    }
    if (count) *count = 0;
    return nullptr;
}

} // namespace sts2
